-- Tiraxis "Explore the Bazaar": the rotation sells every item 15-20% below its Vanity Store price.
-- Each item gets the ItemExtendedCost row (975001 x count, ItemExtendedCost.dbc) whose count lies between 80% and 85%
-- of coa_client_vanity_collection.BazaarTokenCost, nearest to 82.5%; with no row in that range, the nearest row below it.
-- Items the store no longer sells (price 0) keep four times their VanityCollection price.
-- Wooly White Rhino and the four drake reins leave the pool: the store no longer sells them.
-- Fixed values per item, so a reapply changes nothing; band is unchanged, so a rotation keeps
-- drawing the same mix of items. Only on realms with a priced Vanity Store; other realms keep the
-- VanityCollection prices. The pool and a running rotation load at worldserver start.
DELETE FROM `ethereal_bazaar_pool`
WHERE `item` IN (54068, 203080, 203081, 203082, 291915) -- Wooly White Rhino, Lumi'ara's, Verdara's, Nyxaroth's Reins, Reins of the Unbound Star-Eater
AND EXISTS (SELECT 1 FROM `coa_client_vanity_collection` WHERE `BazaarTokenCost` > 0);

UPDATE `ethereal_bazaar_pool` `p`
JOIN (VALUES
